namespace sv_70e02351aa8c494f87a7022cf80de15b.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and broadcasts
/// updates to all subscribed components in the same circuit.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random _rng = Random.Shared;

    private int _lastCount;
    public int LastLowStockCount => _lastCount;

    /// <summary>Raised after new alert data is fetched so every subscriber can re-render.</summary>
    public event Func<Task>? OnAlertDataChanged;

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency-free DB call; return 0-15.
        return Task.FromResult(_rng.Next(0, 16));
    }

    /// <summary>
    /// Fetches a new count for the given warehouse and notifies all subscribers.
    /// Called by whichever component owns the polling loop.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _lastCount = await GetLowStockCountAsync(warehouseId);

        if (OnAlertDataChanged is not null)
            await OnAlertDataChanged.Invoke();
    }
}

