@page "/dashboard"
@rendermode InteractiveServer
@using sv_70e02351aa8c494f87a7022cf80de15b.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-4" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouse.Name</h5>

        <p class="card-text">
            Low-stock alerts:
            @if (_lowStockCount.HasValue)
            {
                <span class="badge @(_lowStockCount > 0 ? "bg-danger" : "bg-success") fs-6">
                    @_lowStockCount
                </span>
            }
            else
            {
                <span class="text-muted">Loading…</span>
            }
        </p>

        <p class="text-muted small mb-0">
            Polling every 10 seconds. Last checked: @(_lastChecked?.ToString("T") ?? "—")
        </p>
    </div>
</div>

@code {
    private int? _lowStockCount;
    private DateTime? _lastChecked;
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;

        // Perform initial fetch and start polling.
        await RefreshAndStartPolling();
    }

    private async Task HandleWarehouseChanged()
    {
        // Warehouse changed → restart polling for new warehouse.
        await InvokeAsync(async () =>
        {
            StopPolling();
            _lowStockCount = null;
            StateHasChanged();
            await RefreshAndStartPolling();
        });
    }

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(() =>
        {
            _lowStockCount = AlertService.LastLowStockCount;
            _lastChecked = DateTime.Now;
            StateHasChanged();
        });
    }

    private async Task RefreshAndStartPolling()
    {
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);

        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
        }
        catch (OperationCanceledException) { }
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

